%% GRAIL_SIMULINK_COMPLETE_FINAL_V22
% Self-contained GRAIL annual MATLAB/Simulink model (8760 h input embedded).
% No xcos_inputs.csv is needed.
%
% Run:     GRAIL_simulink_complete_FINAL_v22
% Output:  GRAIL_system_v22.slx, simulink_results.csv
%
% V22 = V20 with a cleaner print layout (outputs moved to the right, heat-rate
% blocks show f(u), larger fonts). V20 vs V19 - equations, numbers, wiring and solver are UNCHANGED. Only:
%   1. Q_load label corrected to  m_draw cp (Tset - Tmains)  (the block itself
%      already used Tmains; only the text said Tamb).
%   2. One colour per section instead of a different colour on every block.
%   3. Long equation notes split so no text is cut off.
%   4. The diagram left open at the end is the chosen design (parallel, 2 modules).

clc;
here = fileparts(mfilename('fullpath'));
if isempty(here), here = pwd; end

