     8758 0.000000000 293.350000000 295.432083000 0.000000000
     8759 0.000000000 293.260000000 295.472917000 0.000000000
];

%% Validate embedded input data
if size(D,1) ~= 8760, error('Embedded dataset must have 8760 rows; found %d.', size(D,1)); end
if size(D,2) ~= 5,    error('Embedded dataset must have 5 columns.'); end
if any(~isfinite(D(:))), error('Embedded dataset contains NaN or Inf.'); end
if any(D(:,1) ~= (0:8759)'), error('Hour column is not 0..8759.'); end

% Two held samples after 8760 h so the non-interpolating From Workspace
% blocks never extrapolate at the final solver step.
t = [D(:,1); 8760; 8761] * 3600;
D = [D; D(end,:); D(end,:)];
assignin('base','Vg',[t,D(:,2)]);
assignin('base','Va',[t,D(:,3)]);
assignin('base','Vm',[t,D(:,4)]);
assignin('base','Vd',[t,D(:,5)]);
Tc0 = D(1,3);
Tt0 = 298.15;

MDL = 'GRAIL_system_v22';
fprintf('\n============================================================\n');
fprintf(' GRAIL MATLAB / SIMULINK ANNUAL MODEL - V22\n');
fprintf(' Embedded input dataset: %d hourly records\n', size(D,1)-2);
fprintf('============================================================\n');

%% Xcos reference values: arrangement, modules, solar heat [kWh], SF, max Tc [K]
XCOS = { ...
    'alternating', 2, 626.0240, 0.814231, 347.962;
    'parallel',    2, 648.4200, 0.843361, 352.030;
    'alternating', 4, 749.7092, 0.975099, 429.849;
    'parallel',    4, 754.0794, 0.980785, 443.822};

result_file = fullfile(here,'simulink_results.csv');
fid = fopen(result_file,'w');
if fid == -1, error('Could not open simulink_results.csv for writing.'); end
fprintf(fid,['arrangement,n_modules,Q_coll_kWh,Q_loss_kWh,Q_draw_kWh,Q_solar_kWh,Q_load_kWh,', ...
    'pump_h,solar_fraction,Tt_end_K,Tc_max_K,closure_kWh,run_s\n']);
allok = true;

for k = 1:size(XCOS,1)
    arrangement = XCOS{k,1};
    n_modules   = XCOS{k,2};
    fprintf('\n--- Case %d/4: %s, %d modules ---\n', k, arrangement, n_modules);

    p   = grail_params(arrangement, n_modules);
    mdl = build_model(p, MDL, Tc0, Tt0, here, false);

    tic;
    out = sim(mdl,'ReturnWorkspaceOutputs','on');
    rs  = toc;

    E = out.get('E');
    T = out.get('T');
    if isempty(E) || isempty(T) || size(E,2) ~= 6 || size(T,2) ~= 2
        fclose(fid);
        error('Simulink did not return E (6 columns) and T (2 columns).');
    end

    Ef      = E(end,:);
    Tt_end  = T(end,2);
    Tc_max  = max(T(:,1));
    closure = (Ef(1)-Ef(2)-Ef(3)-p.M*p.cp*(Tt_end-Tt0))/3.6e6;   % tank first law
    Q  = Ef(1:5)/3.6e6;                                          % kWh
    pump_h     = Ef(6)/3600;
    solar_frac = Ef(4)/Ef(5);

    fprintf(fid,'%s,%d,%.4f,%.4f,%.4f,%.4f,%.4f,%.2f,%.6f,%.4f,%.3f,%.3e,%.0f\n', ...
        arrangement,n_modules,Q,pump_h,solar_frac,Tt_end,Tc_max,closure,rs);

    dq = 100*(Q(4)/XCOS{k,3}-1);
    dT = Tc_max - XCOS{k,5};
    ok = abs(dq) <= 0.25 && abs(dT) <= 1.5;
    allok = allok && ok;
    if ok, verdict = 'PASS'; else, verdict = 'CHECK'; end

    fprintf('Solar heat     : %.4f kWh\n', Q(4));
    fprintf('Solar fraction : %.4f %%\n', 100*solar_frac);
    fprintf('Max collector  : %.3f K\n', Tc_max);
    fprintf('Tank end       : %.3f K\n', Tt_end);
    fprintf('Energy closure : %.3e kWh\n', closure);
    fprintf('Run time       : %.1f s\n', rs);
    fprintf('vs Xcos        : solar %+.4f %%, max Tc %+.4f K  -> %s\n', dq, dT, verdict);
end
fclose(fid);

fprintf('\n============================================================\n');
if allok
    fprintf('OVERALL PASS (solar heat within 0.25 %%, max Tc within 1.5 K)\n');
else
    fprintf('OVERALL CHECK: at least one case is outside the limits.\n');
end

% Leave the chosen design (parallel, 2 modules) on screen.
build_model(grail_params('parallel',2), MDL, Tc0, Tt0, here, true);
fprintf('Results : %s\n', result_file);
fprintf('Model   : %s (parallel, 2 modules shown)\n', fullfile(here,[MDL '.slx']));
fprintf('============================================================\n');
end

%% ========================================================================
function p = grail_params(arrangement,n_modules)
% Stage-6 coefficients (GRAIL-CHT fit) and system data. Unchanged from V19.
switch lower(arrangement)
    case 'alternating'
        p.e0 = 0.5965906020740813; p.a1 = 2.003882844904737; p.a2 = 0.00037944758755233723;
    case 'parallel'
        p.e0 = 0.6367728001004268; p.a1 = 2.1040764409992594; p.a2 = 0.0;
    otherwise
        error('arrangement must be ''alternating'' or ''parallel''.');
end
p.arrangement = arrangement;
p.n_modules   = n_modules;
p.cp   = 4180;                        % J/(kg K)
p.A    = n_modules*0.528;             % m^2
p.C    = 33500*p.A;                   % J/K
p.g2   = 2*(n_modules*0.00275)*p.cp;  % W/K
p.M    = 100;                         % kg
p.UA   = 1.5;                         % W/K
p.Tset = 318.15;                      % K
p.Tmax = 358.15;                      % K
end

%% ========================================================================
function X = expressions(p)
% Fcn-block equations. Unchanged from V19.
n  = @(v) sprintf('%.17g',v);
mn = @(a,b) ['(((' a ')+(' b ')-abs((' a ')-(' b ')))/2)'];
mx = @(a,b) ['(((' a ')+(' b ')+abs((' a ')-(' b ')))/2)'];
frac = @(Tt,Tmn) mn('1',['(' n(p.Tset) '-' Tmn ')/' mx([Tt '-' Tmn],'1e-9')]);
X.dT           = 'u(1)-u(2)';
X.pump_control = [n(p.Tmax) '-u(2)'];
X.dTc = ['(' n(p.A) '*(' n(p.e0) '*u(1)-' n(p.a1) '*(u(3)-u(2))-' n(p.a2) ...
    '*(u(3)-u(2))*(u(3)-u(2)))-' n(p.g2) '*(u(3)-u(4))*u(5))/' n(p.C)];
X.dTt = ['(' n(p.g2) '*(u(1)-u(2))*u(3)-' n(p.UA) '*(u(2)-u(4))-u(6)*' ...
    frac('u(2)','u(5)') '*' n(p.cp) '*(u(2)-u(5)))/' n(p.M*p.cp)];
X.Q_coll  = [n(p.g2) '*(u(1)-u(2))*u(3)'];
X.Q_loss  = [n(p.UA) '*(u(1)-u(2))'];
X.Q_draw  = ['u(3)*' frac('u(1)','u(2)') '*' n(p.cp) '*(u(1)-u(2))'];
X.Q_solar = mn(['u(3)*' frac('u(1)','u(2)') '*' n(p.cp) '*' mx('u(1)-u(2)','0')], ...
    ['u(3)*' n(p.cp) '*(' n(p.Tset) '-u(2))']);
X.Q_load  = ['u(2)*' n(p.cp) '*(' n(p.Tset) '-u(1))'];   % [Tmains; m_draw]
X.pump_on = 'u(1)';
end

%% ========================================================================
function mdl = build_model(p,mdl,Tc0,Tt0,folder,show)
% Clean presentation layout. Numerics identical to V19; only layout,
% colours and labels changed. One colour per section.
X   = expressions(p);
num = @(v) sprintf('%.17g',v);
at  = @(x,y,w,h) [x y x+w y+h];

if bdIsLoaded(mdl), close_system(mdl,0); end
oldslx = fullfile(folder,[mdl '.slx']);
if exist(oldslx,'file')
    try delete(oldslx); catch ME
        error('Could not replace %s: %s', oldslx, ME.message);
    end
end
new_system(mdl);
load_system('simulink');

L.fcn   = libpath('Fcn','Fcn');
L.int   = libpath('Integrator','Integrator');
L.rel   = libpath('Relay','Relay');
L.sw    = libpath('Switch','Switch');
L.const = libpath('Constant','Constant');
L.mux   = libpath('Mux','Mux');
L.from  = libpath('FromWorkspace','From Workspace');
L.to    = libpath('ToWorkspace','To Workspace');

% ---- one colour per section (pastel, readable with black text) ----------
C.inp  = '[0.80 0.90 1.00]';   % 01 inputs        light blue
C.col  = '[1.00 0.85 0.62]';   % 02 collector     orange
C.tank = '[0.78 0.94 0.80]';   % 03 tank          green
C.pump = '[0.90 0.83 1.00]';   % 04 pump          lilac
C.rate = '[1.00 0.97 0.74]';   % 05 heat rates    pale yellow
C.out  = '[0.88 0.88 0.88]';   % 06 outputs       grey
C.mux  = '[0.25 0.25 0.25]';   % all mux bars     dark grey

    function path = addblk(lib,name,pos,col,varargin)
        path = [mdl '/' name];
        add_block(lib,path,'Position',pos,varargin{:});
        try set_param(path,'BackgroundColor',col,'ForegroundColor','black','FontSize','12'); catch, end
    end
    function addfcn(name,expr,pos,col)
        addblk(L.fcn,name,pos,col,'Expr',expr);
    end
    function addmux(name,nin,pos)
        addblk(L.mux,name,pos,C.mux,'Inputs',num2str(nin),'DisplayOption','bar','ShowName','off');
    end
    function addln(src,dst)
        add_line(mdl,src,dst,'autorouting','smart');
    end
    function addnote(name,text,pos,fs,bold)
        % Visual text only; does not affect simulation.
        a = Simulink.Annotation([mdl '/' name],'FontSize',fs+2,'FontName','Arial','Text',text);
        a.Position = pos;
        if nargin > 4 && bold
            try a.FontWeight = 'bold'; catch, end
        end
    end

set_param(mdl,'Location',[20 20 2650 1150],'ScreenColor','white');

% ---- title and parameters ----------------------------------------------
addnote('TitleNote',sprintf('GRAIL ANNUAL SOLAR WATER HEATER MODEL\n%s arrangement  |  %d modules  |  8760 h', ...
    p.arrangement,p.n_modules),[40 20 900 80],20,true);
addnote('ParamNote',sprintf(['MODEL PARAMETERS\n' ...
    'A = %.6g m^2     C = %.6g J/K     g2 = %.6g W/K     M = %.6g kg     cp = %.6g J/(kg K)\n' ...
    'eta0 = %.10g     a1 = %.10g W/(m^2 K)     a2 = %.10g W/(m^2 K^2)\n' ...
    'UA = %.6g W/K     Tset = %.2f K     Tmax = %.2f K'], ...
    p.A,p.C,p.g2,p.M,p.cp,p.e0,p.a1,p.a2,p.UA,p.Tset,p.Tmax),[1000 20 2250 105],11);

% ---- section headers -----------------------------------------------------
addnote('H1','01  HOURLY INPUTS',                [40 130 400 160],15,true);
addnote('H2','02  COLLECTOR ENERGY BALANCE',     [440 130 1000 160],15,true);
addnote('H3','03  STORAGE TANK BALANCE',         [440 590 1000 620],15,true);
addnote('H4','04  PUMP CONTROL & PROTECTION',    [1060 130 1500 160],15,true);
addnote('H5','05  HEAT RATES [W]',               [1560 130 2250 160],15,true);
addnote('H6','06  ANNUAL TOTALS & OUTPUTS',      [2170 130 2600 160],15,true);

% ---- 01 inputs -----------------------------------------------------------
fw = {'VariableName','Interpolate','off','OutputAfterFinalValue','Holding final value'};
addblk(L.from,'In_Geff',  at(55,190,220,52),C.inp,fw{1},'Vg',fw{2:end});
addblk(L.from,'In_Tamb',  at(55,260,220,52),C.inp,fw{1},'Va',fw{2:end});
addblk(L.from,'In_Tmains',at(55,330,220,52),C.inp,fw{1},'Vm',fw{2:end});
addblk(L.from,'In_Draw',  at(55,400,220,52),C.inp,fw{1},'Vd',fw{2:end});
addnote('InputDesc',sprintf(['G_eff    solar irradiance [W/m^2]\n' ...
    'T_amb    ambient temperature [K]\n' ...
    'T_mains  mains water temperature [K]\n' ...
    'm_draw   hot-water draw [kg/s]\n' ...
    '(values held constant within each hour)']),[55 470 400 570],10);

% ---- 02 collector --------------------------------------------------------
addmux('Mux_dTc',5,at(455,200,12,165));
addfcn('Fcn_dTc_dt',X.dTc,at(515,255,300,58),C.col);
addblk(L.int,'Integrator_Tc',at(855,255,110,55),C.col,'InitialCondition',num(Tc0),'LimitOutput','off');
addnote('CollectorEq',sprintf(['C dTc/dt = A[eta0 G - a1(Tc-Ta) - a2(Tc-Ta)^2]\n' ...
    '                - g2 (Tc-Tt) P\n' ...
    'inputs: [G, Ta, Tc, Tt, P]      output: Tc(t) [K]']),[455 395 1000 470],10);

% ---- 03 tank ---------------------------------------------------------------
addmux('Mux_dTt',6,at(455,650,12,180));
addfcn('Fcn_dTt_dt',X.dTt,at(515,710,300,58),C.tank);
addblk(L.int,'Integrator_Tt',at(855,710,110,55),C.tank,'InitialCondition',num(Tt0),'LimitOutput','off');
addnote('TankEq',sprintf(['M cp dTt/dt = g2 (Tc-Tt) P - UA (Tt-Ta)\n' ...
    '                   - m_t cp (Tt-Tmains)\n' ...
    'm_t = m_draw min(1, (Tset-Tmains)/(Tt-Tmains))   (mixing valve)\n' ...
    'inputs: [Tc, Tt, P, Ta, Tmains, m_draw]      output: Tt(t) [K]']),[455 850 1030 960],10);

% ---- 04 pump ---------------------------------------------------------------
addmux('Mux_PumpDeltaT',2,at(1070,200,12,60));
addfcn('Fcn_PumpDeltaT',X.dT,at(1110,205,150,48),C.pump);
addblk(L.rel,'Relay_Pump',at(1300,205,110,50),C.pump,'OnSwitchValue','7','OffSwitchValue','2', ...
    'OnOutputValue','1','OffOutputValue','0');
addmux('Mux_PumpEnable',2,at(1070,305,12,60));
addfcn('Fcn_PumpLimitControl',X.pump_control,at(1140,310,90,48),C.pump);
addblk(L.sw,'Switch_PumpLimit',at(1300,305,120,58),C.pump,'Criteria','u2 >= Threshold', ...
    'Threshold','0','ZeroCross','off');
addblk(L.const,'Const_PumpOff',at(1130,395,95,35),C.pump,'Value','0');
addnote('PumpEq',sprintf(['DeltaT = Tc - Tt\n' ...
    'Relay: ON at DeltaT >= 7 K, OFF at DeltaT <= 2 K\n' ...
    'Protection: P = Relay if Tt <= %.2f K, else P = 0'],p.Tmax),[1070 460 1500 530],10);

% ---- 05 heat rates ---------------------------------------------------------
y = [190 270 350 430 510 590];
addmux('Mux_Qcoll', 3,at(1570,y(1),12,58)); addfcn('Fcn_Qcoll', X.Q_coll, at(1615,y(1)+8,90,45),C.rate);
addmux('Mux_Qloss', 2,at(1570,y(2),12,58)); addfcn('Fcn_Qloss', X.Q_loss, at(1615,y(2)+8,90,45),C.rate);
addmux('Mux_Qdraw', 3,at(1570,y(3),12,58)); addfcn('Fcn_Qdraw', X.Q_draw, at(1615,y(3)+8,90,45),C.rate);
addmux('Mux_Qsolar',3,at(1570,y(4),12,58)); addfcn('Fcn_Qsolar',X.Q_solar,at(1615,y(4)+8,90,45),C.rate);
addmux('Mux_Qload', 2,at(1570,y(5),12,58)); addfcn('Fcn_Qload', X.Q_load, at(1615,y(5)+8,90,45),C.rate);
addfcn('Fcn_PumpRunning',X.pump_on,at(1615,y(6)+8,90,45),C.rate);
rateTxt = {'Q_coll  = g2 (Tc-Tt) P', 'Q_loss  = UA (Tt-Ta)', 'Q_draw  = m_t cp (Tt-Tmains)', ...
           'Q_solar = min(Q_draw, m_draw cp (Tset-Tmains))', 'Q_load  = m_draw cp (Tset-Tmains)', ...
           'P = 1 when pump runs'};
for ii = 1:6
    addnote(sprintf('RateEq%d',ii),rateTxt{ii},[1725 y(ii)+18 2120 y(ii)+42],10);
end

% ---- 06 outputs -----------------------------------------------------------
addmux('Mux_EnergyRates',6,at(2160,190,12,460));
addblk(L.int,'Integrator_Energy',at(2210,392,110,55),C.out,'InitialCondition','zeros(6,1)','LimitOutput','off');
addblk(L.to,'ToWorkspace_E',at(2360,392,135,55),C.out,'VariableName','E','SaveFormat','Array', ...
    'SampleTime','3600','MaxDataPoints','inf');
addmux('Mux_Temperatures',2,at(2210,720,12,70));
addblk(L.to,'ToWorkspace_T',at(2270,728,135,55),C.out,'VariableName','T','SaveFormat','Array', ...
    'SampleTime','60','MaxDataPoints','inf');
addnote('OutputDesc',sprintf(['E = [Q_coll Q_loss Q_draw Q_solar Q_load pump_s]\n    (J and s; saved hourly)\n' ...
    'T = [Tc  Tt]   (K; saved every 60 s)\n' ...
    'Annual results: simulink_results.csv']),[2170 830 2640 930],10);


% ---- wiring (unchanged from V19) ------------------------------------------
addln('In_Geff/1','Mux_dTc/1');          addln('In_Tamb/1','Mux_dTc/2');
addln('Integrator_Tc/1','Mux_dTc/3');    addln('Integrator_Tt/1','Mux_dTc/4');
addln('Switch_PumpLimit/1','Mux_dTc/5');
addln('Mux_dTc/1','Fcn_dTc_dt/1');       addln('Fcn_dTc_dt/1','Integrator_Tc/1');

addln('Integrator_Tc/1','Mux_dTt/1');    addln('Integrator_Tt/1','Mux_dTt/2');
addln('Switch_PumpLimit/1','Mux_dTt/3'); addln('In_Tamb/1','Mux_dTt/4');
addln('In_Tmains/1','Mux_dTt/5');        addln('In_Draw/1','Mux_dTt/6');
addln('Mux_dTt/1','Fcn_dTt_dt/1');       addln('Fcn_dTt_dt/1','Integrator_Tt/1');

addln('Integrator_Tc/1','Mux_PumpDeltaT/1');  addln('Integrator_Tt/1','Mux_PumpDeltaT/2');
addln('Mux_PumpDeltaT/1','Fcn_PumpDeltaT/1'); addln('Fcn_PumpDeltaT/1','Relay_Pump/1');
addln('Relay_Pump/1','Mux_PumpEnable/1');     addln('Integrator_Tt/1','Mux_PumpEnable/2');
addln('Mux_PumpEnable/1','Fcn_PumpLimitControl/1');
addln('Relay_Pump/1','Switch_PumpLimit/1');
addln('Fcn_PumpLimitControl/1','Switch_PumpLimit/2');
addln('Const_PumpOff/1','Switch_PumpLimit/3');

addln('Integrator_Tc/1','Mux_Qcoll/1'); addln('Integrator_Tt/1','Mux_Qcoll/2');
addln('Switch_PumpLimit/1','Mux_Qcoll/3'); addln('Mux_Qcoll/1','Fcn_Qcoll/1');
addln('Integrator_Tt/1','Mux_Qloss/1'); addln('In_Tamb/1','Mux_Qloss/2'); addln('Mux_Qloss/1','Fcn_Qloss/1');
addln('Integrator_Tt/1','Mux_Qdraw/1'); addln('In_Tmains/1','Mux_Qdraw/2');
addln('In_Draw/1','Mux_Qdraw/3');       addln('Mux_Qdraw/1','Fcn_Qdraw/1');
addln('Integrator_Tt/1','Mux_Qsolar/1'); addln('In_Tmains/1','Mux_Qsolar/2');
addln('In_Draw/1','Mux_Qsolar/3');       addln('Mux_Qsolar/1','Fcn_Qsolar/1');
addln('In_Tmains/1','Mux_Qload/1');      addln('In_Draw/1','Mux_Qload/2'); addln('Mux_Qload/1','Fcn_Qload/1');
addln('Switch_PumpLimit/1','Fcn_PumpRunning/1');

eb = {'Fcn_Qcoll','Fcn_Qloss','Fcn_Qdraw','Fcn_Qsolar','Fcn_Qload','Fcn_PumpRunning'};
for ii = 1:6, addln([eb{ii} '/1'],sprintf('Mux_EnergyRates/%d',ii)); end
addln('Mux_EnergyRates/1','Integrator_Energy/1');
addln('Integrator_Energy/1','ToWorkspace_E/1');
addln('Integrator_Tc/1','Mux_Temperatures/1');
addln('Integrator_Tt/1','Mux_Temperatures/2');
addln('Mux_Temperatures/1','ToWorkspace_T/1');

% ---- solver: same as V19 ---------------------------------------------------
set_param(mdl,'StopTime',num(8760*3600),'Solver','ode45','RelTol','1e-6','AbsTol','1e-6','MaxStep','60');

addnote('Footer',['Colour = section. Layout, colours and labels do not change the numerical model. ' ...
    'SI units; temperatures in K.'],[40 1010 1400 1035],10);

save_system(mdl,fullfile(folder,[mdl '.slx']));
if show, open_system(mdl); end
end

%% ========================================================================
function lib = libpath(blockType,blockName)
% Resolve a standard Simulink library block (unchanged from V19).
load_system('simulink');
switch lower(strtrim(blockName))
    case 'fcn',            candidates = {'simulink/User-Defined Functions/Fcn','simulink/Math Operations/Fcn'};
    case 'integrator',     candidates = {'simulink/Continuous/Integrator'};
    case 'relay',          candidates = {'simulink/Discontinuities/Relay'};
    case 'mux',            candidates = {'simulink/Signal Routing/Mux'};
    case 'switch',         candidates = {'simulink/Signal Routing/Switch','simulink/Commonly Used Blocks/Switch'};
    case 'constant',       candidates = {'simulink/Sources/Constant'};
    case 'from workspace', candidates = {'simulink/Sources/From Workspace'};
    case 'to workspace',   candidates = {'simulink/Sinks/To Workspace'};
    otherwise,             candidates = {};
end
for k = 1:numel(candidates)
    try
        if getSimulinkBlockHandle(candidates{k}) ~= -1, lib = candidates{k}; return; end
    catch
    end
end
try
    hits = find_system('simulink','MatchFilter',@Simulink.match.allVariants, ...
        'LookUnderMasks','all','FollowLinks','on','BlockType',blockType,'Name',blockName);
    if ~isempty(hits), lib = hits{1}; return; end
catch
end
hits = find_system('simulink','LookUnderMasks','all','FollowLinks','on', ...
    'BlockType',blockType,'Name',blockName);
if ~isempty(hits), lib = hits{1}; return; end
error('Could not find Simulink library block %s (%s).',blockName,blockType);
end
